package kz.printlab.controller; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import kz.printlab.dto.RegisterRequest; import kz.printlab.service.AuthService;
@Controller public class AuthController {private final AuthService auth; public AuthController(AuthService a){auth=a;} @GetMapping("/register") public String register(Model m){m.addAttribute("registerRequest",new RegisterRequest());return "register";} @PostMapping("/register") public String registerSubmit(@Valid @ModelAttribute RegisterRequest r,BindingResult errors){if(r.getPassword()!=null && !r.getPassword().equals(r.getConfirmPassword())) errors.rejectValue("confirmPassword","mismatch","Пароли не совпадают"); if(r.getPassword()!=null && r.getPassword().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72) errors.rejectValue("password","tooLong","Пароль слишком длинный для безопасного хранения"); if(errors.hasErrors()) return "register";try{auth.registerUser(r);}catch(AuthService.DuplicateEmailException ex){errors.rejectValue("email","duplicate","Этот email уже зарегистрирован");return "register";}return "redirect:/login?registered";} @GetMapping("/login") public String login(){return "login";}}
